if (
  inputPayload &&
  inputPayload["OBJECT_LIST(76)"] &&
  Array.isArray(inputPayload["OBJECT_LIST(76)"])
) {
  // Iterate through the OBJECT_LIST array to find the specified objects
  for (var i = 0; i < inputPayload["OBJECT_LIST(76)"].length; i++) {
    var object = inputPayload["OBJECT_LIST(76)"][i];

    // Check if the object name is in the list of objects to extract
    if (orderOfKeys.includes(object["OBJECT_NAME(77)"])) {
      // Extract the value and round it to 2 decimal places
      var value;

      // Handle special cases for "State.Heater" and "State.Chiller"
      if (object["OBJECT_NAME(77)"] === "State.Heater" || object["OBJECT_NAME(77)"] === "State.Chiller") {
        // Set output as true for "ACTIVE(1)" and false for "INACTIVE(0)"
        value = object["PRESENT_VALUE(85)"] === "ACTIVE(1)";
      } else {
        // For other objects, round the value to 2 decimal places
        value = parseFloat(object["PRESENT_VALUE(85)"]).toFixed(2);
      }

      // Add the value to the extractedData object
      extractedData[object["OBJECT_NAME(77)"]] = value;
    }
  }
}

// Create an array to store the values in the defined order
var outputArray = orderOfKeys.map(function(key) {
  return extractedData[key];
});

// Send the extracted data as the output
msg.payload = outputArray;
return msg;

